    fn parse_system_profiler_garbage_is_unknown() {
        let (name, vram, kind) = parse_system_profiler("this is not display info at all");
        assert_eq!(name, "unknown");
        assert_eq!(vram, None);
        assert_eq!(kind, "unknown");
